
/* Integer rectangle operations use widened endpoints to avoid signed overflow. */
#include <SDL.h>
#include <limits.h>
bool SDL_GetRectIntersection(const SDL_Rect *a,const SDL_Rect *b,SDL_Rect *r){if(!a||!b||!r)return SDL_SetError("Invalid rectangle");Sint64 x=SDL_max(a->x,b->x),y=SDL_max(a->y,b->y);Sint64 right=SDL_min((Sint64)a->x+a->w,(Sint64)b->x+b->w),bottom=SDL_min((Sint64)a->y+a->h,(Sint64)b->y+b->h);r->x=(int)x;r->y=(int)y;r->w=right>x?(int)(right-x):0;r->h=bottom>y?(int)(bottom-y):0;if(SDL_RectEmpty(a)||SDL_RectEmpty(b)){r->w=0;r->h=0;}return r->w>0&&r->h>0;}
bool SDL_HasRectIntersection(const SDL_Rect *a,const SDL_Rect *b){SDL_Rect r;return SDL_GetRectIntersection(a,b,&r);}
bool SDL_GetRectUnion(const SDL_Rect *a,const SDL_Rect *b,SDL_Rect *r){if(!a||!b||!r)return SDL_SetError("Invalid rectangle");if(SDL_RectEmpty(a)){if(SDL_RectEmpty(b))SDL_zero(*r);else *r=*b;return 1;}if(SDL_RectEmpty(b)){*r=*a;return 1;}Sint64 x=SDL_min(a->x,b->x),y=SDL_min(a->y,b->y);Sint64 right=SDL_max((Sint64)a->x+a->w,(Sint64)b->x+b->w),bottom=SDL_max((Sint64)a->y+a->h,(Sint64)b->y+b->h);if(right-x>INT_MAX||bottom-y>INT_MAX)return SDL_SetError("Rectangle union exceeds integer range");r->x=x;r->y=y;r->w=right-x;r->h=bottom-y;return 1;}
static int rect_outcode(Sint64 x,Sint64 y,Sint64 left,Sint64 top,Sint64 right,Sint64 bottom){return (x<left?1:0)|(x>right?2:0)|(y<top?4:0)|(y>bottom?8:0);}
bool SDL_GetRectAndLineIntersection(const SDL_Rect *r,int *px1,int *py1,int *px2,int *py2){if(!r||!px1||!py1||!px2||!py2)return SDL_SetError("Invalid line intersection parameter");if(SDL_RectEmpty(r))return 0;Sint64 left=r->x,top=r->y,right=left+r->w-1,bottom=top+r->h-1;Sint64 x1=*px1,y1=*py1,x2=*px2,y2=*py2;int c1=rect_outcode(x1,y1,left,top,right,bottom),c2=rect_outcode(x2,y2,left,top,right,bottom);while(c1||c2){if(c1&c2)return 0;int c=c1?c1:c2;Sint64 x,y;/* double prevents overflow of a 32-bit endpoint difference product. */if(c&4){y=top;x=x1+(Sint64)((double)(x2-x1)*(double)(top-y1)/(double)(y2-y1));}else if(c&8){y=bottom;x=x1+(Sint64)((double)(x2-x1)*(double)(bottom-y1)/(double)(y2-y1));}else if(c&2){x=right;y=y1+(Sint64)((double)(y2-y1)*(double)(right-x1)/(double)(x2-x1));}else{x=left;y=y1+(Sint64)((double)(y2-y1)*(double)(left-x1)/(double)(x2-x1));}if(c==c1){x1=x;y1=y;c1=rect_outcode(x1,y1,left,top,right,bottom);}else{x2=x;y2=y;c2=rect_outcode(x2,y2,left,top,right,bottom);}}*px1=x1;*py1=y1;*px2=x2;*py2=y2;return 1;}
bool SDL_GetRectEnclosingPoints(const SDL_Point *points,int count,const SDL_Rect *clip,SDL_Rect *r){if(!points||count<=0)return SDL_SetError("Invalid points");if(clip&&SDL_RectEmpty(clip))return 0;bool found=0;int minx=0,miny=0,maxx=0,maxy=0;for(int i=0;i<count;i++){const SDL_Point *p=&points[i];if(clip&&!SDL_PointInRect(p,clip))continue;if(!r)return 1;if(!found){minx=maxx=p->x;miny=maxy=p->y;found=1;}else{minx=SDL_min(minx,p->x);miny=SDL_min(miny,p->y);maxx=SDL_max(maxx,p->x);maxy=SDL_max(maxy,p->y);}}if(!found)return 0;if((Sint64)maxx-minx+1>INT_MAX||(Sint64)maxy-miny+1>INT_MAX)return SDL_SetError("Enclosing rectangle exceeds integer range");r->x=minx;r->y=miny;r->w=maxx-minx+1;r->h=maxy-miny+1;return 1;}
